{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur le droit de la personne assurée à une allocation pour impotent de degré grave et sur le début de ce droit, antérieur au 1er avril 2023.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La personne assurée a été alimentée par sonde naso-gastrique de décembre 2023 à fin avril 2024, ce qui ne suffit pas à retenir un besoin d'aide régulière et importante pour l'acte « manger », la durée étant inférieure à une année.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "L'aide pour apporter un repas au fauteuil ou l'installer à table relève des actes « se lever, s'asseoir, se coucher » et « se déplacer », déjà pris en compte pour l'impotence.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le droit à une allocation pour impotent de degré grave suppose un besoin d'aide régulière et importante pour tous les actes ordinaires de la vie et des soins ou une surveillance permanente, conditions non remplies en l'espèce.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Si l'assuré fait valoir son droit plus de douze mois après sa naissance, l'allocation n'est versée que pour les douze mois précédant la demande.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Une aide ponctuelle pour couper des aliments durs ou un accompagnement psychologique non médicalement attesté ne constitue pas un besoin d'aide régulière et importante pour l'acte « manger ».",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme l'absence d'un besoin d'aide régulière et importante pour l'acte « manger », de sorte qu'une impotence grave ne peut être reconnue.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "L'allocation pour impotent de degré moyen est versée à la personne assurée dès le 1er avril 2023, soit les douze mois précédant sa demande.",
      "b_propositions": ["P8"]
    }
  ]
}
